const packKeys = ["pf2e.classes", "battlezoo-eldamon-pf2e.classes"];
const classesData = [];
for (const pack of game.packs.filter(p => packKeys.includes(p.collection))) {
  classesData.push(...(await pack.getIndex()));
}

const module = game.modules.get("pf2e-dual-class");
const picked = await module.api.promptForTwoClasses(classesData);
if (picked) await module.api.createDualClassItem(picked.class1, picked.class2);
